// Arma el registro de memoria: cuenta mensajes del cliente, construye el historial y fusiona los datos clave.
const ctx = $('Contexto listo').first().json;
const cls = $('Limpiar clasificación').first().json;
const fin = $('Unificar respuesta').first().json;

const msgs = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const arr = Array.isArray(j.messages) ? j.messages : [j];
  for (const m of arr) msgs.push(m);
}
const txt = (v) => (typeof v === 'string' ? v : (v && typeof v.content === 'string' ? v.content : ''));
const lines = [];
let humanos = 0;
for (const m of msgs) {
  const h = m.human !== undefined ? txt(m.human) : ((m.type === 'human' || m.role === 'user') ? txt(m.content) : '');
  const a = m.ai !== undefined ? txt(m.ai) : ((m.type === 'ai' || m.role === 'assistant') ? txt(m.content) : '');
  if (h) { humanos++; lines.push('Cliente: ' + h); }
  else if (a) { lines.push('Agente: ' + a); }
}

let prev = {};
try { prev = JSON.parse(ctx.datos_clave || '{}'); } catch (e) { prev = {}; }
const pick = (n, p) => ((n && String(n).trim()) ? String(n).trim() : (p || ''));
const datos = {
  nombre: pick(cls.nombre, prev.nombre),
  marca: pick(cls.marca, prev.marca),
  modelo: pick(cls.modelo, prev.modelo),
  problema: pick(cls.problema, prev.problema),
  reparacion: pick(cls.reparacion, prev.reparacion),
  ultima_intencion: pick(cls.intencion, prev.ultima_intencion),
  mensajes: humanos
};

const mapaEstado = { exito: 'resuelto', escalado: 'derivado a humano', error: 'requiere atención humana' };
const saludo = (ctx.user_name && ctx.user_name !== 'cliente') ? ('Hola ' + ctx.user_name + '. ') : '';

return [{ json: {
  session_id: ctx.session_id,
  fecha: fin.fecha,
  mensajes: humanos,
  historial: lines.join('\n'),
  resumen_actual: ctx.resumen_raw || '',
  datos_clave: JSON.stringify(datos),
  estado_caso: mapaEstado[fin.estado] || 'en curso',
  saludo
} }];

// Valida que la salida del resumidor cumpla el esquema {asunto_principal, puntos_clave[], accion_requerida}.
const base = $('Preparar registro de memoria').first().json;
const raw = String($json.output || '').replace(/<think>[\s\S]*?<\/think>/g, '');
let o = {};
try { o = JSON.parse((raw.match(/\{[\s\S]*\}/) || ['{}'])[0]); } catch (e) { o = {}; }
const resumen = {
  asunto_principal: typeof o.asunto_principal === 'string' && o.asunto_principal ? o.asunto_principal : 'Consulta del cliente sobre su equipo',
  puntos_clave: Array.isArray(o.puntos_clave) ? o.puntos_clave.map(String) : [],
  accion_requerida: typeof o.accion_requerida === 'string' && o.accion_requerida ? o.accion_requerida : 'Revisión manual'
};
return [{ json: { ...base, resumen_json: JSON.stringify(resumen) } }];

